// Ecommerce Home Page - Interactive Features
// ============================================

document.addEventListener('DOMContentLoaded', function() {
  initializeCart();
  initializeNewsletterForm();
  initializeInteractiveButtons();
});

// ============================================
// Cart Functionality
// ============================================

function initializeCart() {
  const addToCartButtons = document.querySelectorAll('.product-card .btn-secondary, .deal-card .btn');
  const cartButton = document.querySelector('.cart-btn');

  addToCartButtons.forEach(button => {
    button.addEventListener('click', function(e) {
      e.preventDefault();
      handleAddToCart(button);
    });
  });

  cartButton.addEventListener('click', function() {
    showCartNotification();
  });
}

function handleAddToCart(button) {
  const productCard = button.closest('.product-card') || button.closest('.deal-card');
  let productName = '';

  if (button.closest('.product-card')) {
    productName = productCard.querySelector('.product-info h3')?.textContent || 'Product';
  } else if (button.closest('.deal-card')) {
    productName = productCard.querySelector('.deal-info h3')?.textContent || 'Deal';
  }

  const cartCount = document.querySelector('.cart-count');
  const currentCount = parseInt(cartCount.textContent) || 0;
  cartCount.textContent = currentCount + 1;
  cartCount.setAttribute('aria-label', `${currentCount + 1} item${currentCount + 1 > 1 ? 's' : ''} in cart`);

  showNotification(`Added "${productName}" to cart`);
  animateButton(button);
}

function animateButton(button) {
  button.style.transform = 'scale(0.95)';
  setTimeout(() => {
    button.style.transform = 'scale(1)';
  }, 200);
}

function showCartNotification() {
  const cartCount = parseInt(document.querySelector('.cart-count').textContent);
  showNotification(`Cart contains ${cartCount} item${cartCount > 1 ? 's' : ''}`);
}

// ============================================
// Newsletter Form
// ============================================

function initializeNewsletterForm() {
  const form = document.querySelector('.newsletter-form');
  if (form) {
    form.addEventListener('submit', handleNewsletterSubmit);
  }
}

function handleNewsletterSubmit(event) {
  event.preventDefault();

  const emailInput = event.target.querySelector('input[type="email"]');
  const email = emailInput.value;

  if (validateEmail(email)) {
    showNotification(`Welcome! Confirmation sent to ${email}`);
    emailInput.value = '';
  } else {
    showNotification('Please enter a valid email address', 'error');
  }
}

function validateEmail(email) {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(email);
}

// ============================================
// Interactive Button Features
// ============================================

function initializeInteractiveButtons() {
  const viewDealButtons = document.querySelectorAll('.deal-card .btn-accent');

  viewDealButtons.forEach(button => {
    button.addEventListener('click', function(e) {
      e.preventDefault();
      const dealCard = this.closest('.deal-card');
      const dealTitle = dealCard.querySelector('h3').textContent;
      showNotification(`Viewing deal: ${dealTitle}`);
    });
  });

  const articleLinks = document.querySelectorAll('.article-link');
  articleLinks.forEach(link => {
    link.addEventListener('click', function(e) {
      e.preventDefault();
      const articleTitle = this.closest('.article-content')?.querySelector('h3')?.textContent;
      showNotification(`Opening article: ${articleTitle}`);
    });
  });

  const searchButton = document.querySelector('.search-btn');
  if (searchButton) {
    searchButton.addEventListener('click', function() {
      showNotification('Search functionality coming soon');
    });
  }
}

// ============================================
// Notification System
// ============================================

function showNotification(message, type = 'success') {
  const notification = document.createElement('div');
  notification.className = `notification notification-${type}`;
  notification.setAttribute('role', 'status');
  notification.setAttribute('aria-live', 'polite');
  notification.setAttribute('aria-atomic', 'true');

  notification.textContent = message;

  notification.style.cssText = `
    position: fixed;
    bottom: 2rem;
    right: 2rem;
    background: ${type === 'error' ? 'rgba(255, 107, 157, 0.9)' : 'rgba(74, 158, 255, 0.9)'};
    color: #0f0f0f;
    padding: 1rem 1.5rem;
    border-radius: 4px;
    font-weight: 600;
    z-index: 1000;
    animation: slideIn 0.3s ease-out;
    box-shadow: 0 8px 25px rgba(0, 0, 0, 0.3);
  `;

  document.body.appendChild(notification);

  setTimeout(() => {
    notification.style.animation = 'slideOut 0.3s ease-out';
    setTimeout(() => {
      notification.remove();
    }, 300);
  }, 3000);
}

