/* ============================================
   Reset & Base Styles
   ============================================ */

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
  background: linear-gradient(135deg, #0f0f0f 0%, #1a1a1a 100%);
  color: #e8e8e8;
  line-height: 1.6;
  min-height: 100vh;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: #4a9eff;
  text-decoration: none;
  transition: color 0.3s ease;
}

a:hover,
a:focus {
  color: #6bb3ff;
  outline: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
}

/* ============================================
   Accessibility
   ============================================ */

.skip-link {
  position: absolute;
  top: -40px;
  left: 0;
  background: #4a9eff;
  color: #0f0f0f;
  padding: 8px 16px;
  text-decoration: none;
  z-index: 100;
  border-radius: 0 0 4px 0;
  font-weight: 600;
}

.skip-link:focus {
  top: 0;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border-width: 0;
}

/* ============================================
   Focus Styles
   ============================================ */

:focus-visible {
  outline: 3px solid #4a9eff;
  outline-offset: 2px;
}

/* ============================================
   Header
   ============================================ */

.header {
  background: rgba(20, 20, 20, 0.95);
  border-bottom: 1px solid rgba(74, 158, 255, 0.2);
  position: sticky;
  top: 0;
  z-index: 50;
  backdrop-filter: blur(10px);
}

.header-container {
  max-width: 1400px;
  margin: 0 auto;
  padding: 1rem 2rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 2rem;
}

.logo h1 {
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -1px;
  background: linear-gradient(135deg, #4a9eff 0%, #66d9ff 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.nav-primary ul {
  display: flex;
  list-style: none;
  gap: 2rem;
  margin: 0;
}

.nav-primary a {
  font-size: 0.95rem;
  color: #e8e8e8;
  transition: color 0.3s ease;
}

.nav-primary a:hover,
.nav-primary a:focus {
  color: #4a9eff;
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.icon-btn {
  background: transparent;
  color: #e8e8e8;
  font-size: 1.25rem;
  padding: 0.5rem;
  border-radius: 4px;
  transition: background-color 0.3s ease, color 0.3s ease;
}

.icon-btn:hover,
.icon-btn:focus {
  background-color: rgba(74, 158, 255, 0.1);
  color: #4a9eff;
}

.cart-btn {
  position: relative;
}

.cart-count {
  position: absolute;
  top: -8px;
  right: -8px;
  background: #ff6b9d;
  color: #fff;
  border-radius: 50%;
  width: 20px;
  height: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.75rem;
  font-weight: 600;
}

/* ============================================
   Hero Section
   ============================================ */

.hero {
  background: linear-gradient(135deg, #1a2a3a 0%, #2a3a4a 100%);
  padding: 8rem 2rem;
  text-align: center;
  border-bottom: 1px solid rgba(74, 158, 255, 0.2);
}

.hero-content h2 {
  font-size: 3rem;
  margin-bottom: 1rem;
  background: linear-gradient(135deg, #66d9ff 0%, #4a9eff 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  line-height: 1.2;
}

.hero-content p {
  font-size: 1.25rem;
  color: #b8b8b8;
  margin-bottom: 2rem;
}

/* ============================================
   Container
   ============================================ */

.container {
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 2rem;
}

/* ============================================
   Section Styles
   ============================================ */

main > section {
  padding: 4rem 0;
  border-bottom: 1px solid rgba(74, 158, 255, 0.1);
}

main > section h2 {
  font-size: 2rem;
  margin-bottom: 3rem;
  color: #e8e8e8;
  position: relative;
  padding-bottom: 1rem;
}

main > section h2::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 60px;
  height: 3px;
  background: linear-gradient(90deg, #4a9eff, #66d9ff);
  border-radius: 2px;
}

/* ============================================
   Buttons
   ============================================ */

.btn {
  padding: 0.75rem 1.5rem;
  border-radius: 4px;
  font-weight: 600;
  transition: all 0.3s ease;
  cursor: pointer;
  display: inline-block;
  text-align: center;
  border: 2px solid transparent;
  font-size: 1rem;
}

.btn-primary {
  background: linear-gradient(135deg, #4a9eff 0%, #66d9ff 100%);
  color: #0f0f0f;
}

.btn-primary:hover,
.btn-primary:focus {
  transform: translateY(-2px);
  box-shadow: 0 8px 20px rgba(74, 158, 255, 0.3);
}

.btn-secondary {
  background: rgba(74, 158, 255, 0.15);
  color: #e8e8e8;
  border: 2px solid rgba(74, 158, 255, 0.3);
}

.btn-secondary:hover,
.btn-secondary:focus {
  background: rgba(74, 158, 255, 0.25);
  border-color: #4a9eff;
}

.btn-accent {
  background: rgba(255, 107, 157, 0.15);
  color: #e8e8e8;
  border: 2px solid rgba(255, 107, 157, 0.3);
}

.btn-accent:hover,
.btn-accent:focus {
  background: rgba(255, 107, 157, 0.25);
  border-color: #ff6b9d;
}

.btn-sm {
  padding: 0.5rem 1rem;
  font-size: 0.9rem;
}

/* ============================================
   Products Grid
   ============================================ */

.products-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 2rem;
}

.product-card {
  background: rgba(40, 40, 40, 0.6);
  border: 1px solid rgba(74, 158, 255, 0.15);
  border-radius: 8px;
  overflow: hidden;
  transition: all 0.3s ease;
  display: flex;
  flex-direction: column;
}

.product-card:hover,
.product-card:focus-within {
  border-color: rgba(74, 158, 255, 0.4);
  background: rgba(40, 40, 40, 0.9);
  transform: translateY(-4px);
  box-shadow: 0 12px 30px rgba(74, 158, 255, 0.2);
}

.product-image {
  position: relative;
  overflow: hidden;
  padding-top: 100%;
  background: linear-gradient(135deg, #2a2a2a 0%, #1a1a1a 100%);
}

.product-image img {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.badge {
  position: absolute;
  top: 1rem;
  right: 1rem;
  background: #4a9eff;
  color: #0f0f0f;
  padding: 0.4rem 0.8rem;
  border-radius: 4px;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  z-index: 2;
}

.badge-new {
  background: #4a9eff;
}

.badge-limited {
  background: #ff6b9d;
}

.badge-bestseller {
  background: #ffd700;
  color: #0f0f0f;
}

.product-info {
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  flex-grow: 1;
}

.product-info h3 {
  font-size: 1.1rem;
  margin-bottom: 0.5rem;
  color: #e8e8e8;
}

.category {
  color: #888;
  font-size: 0.85rem;
  margin-bottom: 0.75rem;
}

.rating {
  font-size: 0.9rem;
  color: #ffd700;
  margin-bottom: 1rem;
  letter-spacing: 1px;
}

.price {
  margin-bottom: 1rem;
  display: flex;
  align-items: center;
  gap: 1rem;
}

.current-price {
  font-size: 1.5rem;
  font-weight: 700;
  color: #4a9eff;
}

.product-card .btn {
  margin-top: auto;
  width: 100%;
}

/* ============================================
   Deals Section
   ============================================ */

.deals-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 2rem;
}

.deal-card {
  background: linear-gradient(135deg, rgba(40, 40, 40, 0.8), rgba(30, 30, 30, 0.8));
  border: 1px solid rgba(74, 158, 255, 0.2);
  border-radius: 12px;
  overflow: hidden;
  transition: all 0.3s ease;
  display: flex;
  gap: 1.5rem;
  padding: 1.5rem;
}

.deal-card:hover,
.deal-card:focus-within {
  border-color: #ff6b9d;
  background: linear-gradient(135deg, rgba(50, 50, 50, 0.9), rgba(40, 40, 40, 0.9));
  transform: translateX(4px);
  box-shadow: 0 8px 25px rgba(255, 107, 157, 0.15);
}

.deal-image {
  width: 140px;
  min-width: 140px;
  height: 140px;
  border-radius: 8px;
  overflow: hidden;
}

.deal-image svg {
  width: 100%;
  height: 100%;
}

.deal-info {
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.deal-tag {
  color: #ff6b9d;
  font-size: 0.8rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 0.5rem;
}

.deal-info h3 {
  font-size: 1.3rem;
  margin-bottom: 0.5rem;
  color: #e8e8e8;
}

.discount {
  font-size: 1.1rem;
  color: #4a9eff;
  font-weight: 600;
  margin-bottom: 0.5rem;
}

.ends-in {
  color: #888;
  font-size: 0.9rem;
  margin-bottom: 1rem;
}

.deal-card .btn {
  align-self: flex-start;
}

/* ============================================
   Editorial Section
   ============================================ */

.articles-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(350px, 1fr));
  gap: 2rem;
}

.article-card {
  background: rgba(40, 40, 40, 0.5);
  border: 1px solid rgba(74, 158, 255, 0.15);
  border-radius: 8px;
  overflow: hidden;
  transition: all 0.3s ease;
  display: flex;
  flex-direction: column;
}

.article-card:hover,
.article-card:focus-within {
  border-color: rgba(74, 158, 255, 0.4);
  background: rgba(40, 40, 40, 0.8);
  transform: translateY(-6px);
  box-shadow: 0 15px 35px rgba(74, 158, 255, 0.15);
}

.article-image {
  width: 100%;
  height: 200px;
  overflow: hidden;
  background: linear-gradient(135deg, #2a2a2a 0%, #1a1a1a 100%);
}

.article-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.4s ease;
}

.article-card:hover .article-image img,
.article-card:focus-within .article-image img {
  transform: scale(1.05);
}

.article-content {
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  flex-grow: 1;
}

.article-date {
  color: #888;
  font-size: 0.85rem;
  margin-bottom: 0.75rem;
}

.article-content h3 {
  font-size: 1.2rem;
  margin-bottom: 1rem;
  color: #e8e8e8;
  line-height: 1.4;
}

.article-excerpt {
  color: #b8b8b8;
  margin-bottom: 1.5rem;
  flex-grow: 1;
  font-size: 0.95rem;
}

.article-link {
  color: #4a9eff;
  font-weight: 600;
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  transition: all 0.3s ease;
}

.article-link:hover,
.article-link:focus {
  color: #66d9ff;
  gap: 0.8rem;
}

/* ============================================
   Newsletter Section
   ============================================ */

.newsletter-section {
  background: linear-gradient(135deg, rgba(74, 158, 255, 0.1), rgba(102, 217, 255, 0.05));
  border-top: 1px solid rgba(74, 158, 255, 0.3);
  border-bottom: 1px solid rgba(74, 158, 255, 0.3);
  padding: 4rem 0;
}

.newsletter-container {
  text-align: center;
}

.newsletter-section h2 {
  margin-bottom: 1rem;
  padding-bottom: 0.5rem;
}

.newsletter-section h2::after {
  display: none;
}

.newsletter-section p {
  color: #b8b8b8;
  margin-bottom: 2rem;
  font-size: 1.1rem;
}

.newsletter-form {
  display: flex;
  gap: 0.5rem;
  max-width: 500px;
  margin: 0 auto;
}

.newsletter-form input {
  flex: 1;
  padding: 0.75rem 1rem;
  border: 2px solid rgba(74, 158, 255, 0.3);
  border-radius: 4px;
  background: rgba(20, 20, 20, 0.8);
  color: #e8e8e8;
  font-size: 1rem;
  transition: all 0.3s ease;
}

.newsletter-form input:hover,
.newsletter-form input:focus {
  border-color: #4a9eff;
  background: rgba(20, 20, 20, 0.95);
}

.newsletter-form input::placeholder {
  color: #666;
}

.newsletter-form button {
  white-space: nowrap;
}

/* ============================================
   Footer
   ============================================ */

.footer {
  background: rgba(15, 15, 15, 0.95);
  border-top: 1px solid rgba(74, 158, 255, 0.15);
  padding: 3rem 0 1.5rem;
  margin-top: 2rem;
}

.footer-content {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 2rem;
  margin-bottom: 2rem;
}

.footer-section h3 {
  font-size: 1rem;
  margin-bottom: 1rem;
  color: #4a9eff;
}

.footer-section ul {
  list-style: none;
}

.footer-section ul li {
  margin-bottom: 0.75rem;
}

.footer-section a {
  color: #b8b8b8;
  transition: color 0.3s ease;
}

.footer-section a:hover,
.footer-section a:focus {
  color: #4a9eff;
}

.social-links {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
}

.footer-bottom {
  border-top: 1px solid rgba(74, 158, 255, 0.1);
  padding-top: 1.5rem;
  text-align: center;
  color: #666;
  font-size: 0.9rem;
}

/* ============================================
   Responsive Design
   ============================================ */

@media (max-width: 768px) {
  .header-container {
    padding: 1rem;
    gap: 1rem;
  }

  .logo h1 {
    font-size: 1.25rem;
  }

  .nav-primary ul {
    gap: 1rem;
    font-size: 0.85rem;
  }

  .hero-content h2 {
    font-size: 2rem;
  }

  .hero {
    padding: 4rem 1rem;
  }

  .products-grid {
    grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
    gap: 1rem;
  }

  .deals-grid {
    grid-template-columns: 1fr;
  }

  .deal-card {
    flex-direction: column;
  }

  .deal-image {
    width: 100%;
    height: 150px;
  }

  .articles-grid {
    grid-template-columns: 1fr;
  }

  .newsletter-form {
    flex-direction: column;
  }

  .newsletter-form button {
    width: 100%;
  }

  main > section {
    padding: 2rem 0;
  }

  main > section h2 {
    font-size: 1.5rem;
    margin-bottom: 2rem;
  }

  .footer-content {
    grid-template-columns: repeat(2, 1fr);
    gap: 1.5rem;
  }
}

@media (max-width: 480px) {
  body {
    font-size: 0.9rem;
  }

  .hero-content h2 {
    font-size: 1.5rem;
  }

  .hero {
    padding: 2rem 1rem;
  }

  .container {
    padding: 0 1rem;
  }

  main > section {
    padding: 1.5rem 0;
  }

  main > section h2 {
    font-size: 1.25rem;
    margin-bottom: 1.5rem;
  }

  .product-info h3 {
    font-size: 1rem;
  }

  .deal-card {
    padding: 1rem;
  }

  .footer-content {
    grid-template-columns: 1fr;
    gap: 1.5rem;
  }
}

/* ============================================
   Forced Colors Mode (High Contrast)
   ============================================ */

@media (forced-colors: active) {
  .btn-primary,
  .btn-secondary,
  .btn-accent {
    border: 2px solid;
    background: ButtonFace;
    color: ButtonText;
  }

  .logo h1,
  .hero-content h2 {
    color: CanvasText;
  }

  a {
    color: LinkText;
  }

  a:visited {
    color: VisitedText;
  }

  .badge {
    border: 2px solid;
    background: ButtonFace;
    color: ButtonText;
  }

  button:focus-visible {
    outline: 3px solid;
  }
}

/* ============================================
   Reduced Motion
   ============================================ */

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

// ============================================
// Ecommerce Home Page - Interactive Features
// ============================================

document.addEventListener('DOMContentLoaded', function() {
  initializeCart();
  initializeNewsletterForm();
  initializeInteractiveButtons();
});

// ============================================
// Cart Functionality
// ============================================

function initializeCart() {
  const addToCartButtons = document.querySelectorAll('.product-card .btn-secondary, .deal-card .btn');
  const cartButton = document.querySelector('.cart-btn');

  addToCartButtons.forEach(button => {
    button.addEventListener('click', function(e) {
      e.preventDefault();
      handleAddToCart(button);
    });
  });

  cartButton.addEventListener('click', function() {
    showCartNotification();
  });
}

function handleAddToCart(button) {
  const productCard = button.closest('.product-card') || button.closest('.deal-card');
  let productName = '';

  if (button.closest('.product-card')) {
    productName = productCard.querySelector('.product-info h3')?.textContent || 'Product';
  } else if (button.closest('.deal-card')) {
    productName = productCard.querySelector('.deal-info h3')?.textContent || 'Deal';
  }

  const cartCount = document.querySelector('.cart-count');
  const currentCount = parseInt(cartCount.textContent) || 0;
  cartCount.textContent = currentCount + 1;
  cartCount.setAttribute('aria-label', `${currentCount + 1} item${currentCount + 1 > 1 ? 's' : ''} in cart`);

  showNotification(`Added "${productName}" to cart`);
  animateButton(button);
}

function animateButton(button) {
  button.style.transform = 'scale(0.95)';
  setTimeout(() => {
    button.style.transform = 'scale(1)';
  }, 200);
}

function showCartNotification() {
  const cartCount = parseInt(document.querySelector('.cart-count').textContent);
