+  color: #ffd700;
+  margin-bottom: 1rem;
+  letter-spacing: 1px;
+}
+
+.price {
+  margin-bottom: 1rem;
+  display: flex;
+  align-items: center;
+  gap: 1rem;
+}
+
+.current-price {
+  font-size: 1.5rem;
+  font-weight: 700;
+  color: #4a9eff;
+}
+
+.product-card .btn {
+  margin-top: auto;
+  width: 100%;
+}
+
+/* ============================================
+   Deals Section
+   ============================================ */
+
+.deals-grid {
+  display: grid;
+  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
+  gap: 2rem;
+}
+
+.deal-card {
+  background: linear-gradient(135deg, rgba(40, 40, 40, 0.8), rgba(30, 30, 30, 0.8));
+  border: 1px solid rgba(74, 158, 255, 0.2);
+  border-radius: 12px;
+  overflow: hidden;
+  transition: all 0.3s ease;
+  display: flex;
+  gap: 1.5rem;
+  padding: 1.5rem;
+}
+
+.deal-card:hover,
+.deal-card:focus-within {
+  border-color: #ff6b9d;
+  background: linear-gradient(135deg, rgba(50, 50, 50, 0.9), rgba(40, 40, 40, 0.9));
+  transform: translateX(4px);
+  box-shadow: 0 8px 25px rgba(255, 107, 157, 0.15);
+}
+
+.deal-image {
+  width: 140px;
+  min-width: 140px;
+  height: 140px;
+  border-radius: 8px;
+  overflow: hidden;
+}
+
+.deal-image svg {
+  width: 100%;
+  height: 100%;
+}
+
+.deal-info {
+  flex: 1;
+  display: flex;
+  flex-direction: column;
+  justify-content: space-between;
+}
+
+.deal-tag {
+  color: #ff6b9d;
+  font-size: 0.8rem;
+  font-weight: 700;
+  text-transform: uppercase;
+  letter-spacing: 1px;
+  margin-bottom: 0.5rem;
+}
+
+.deal-info h3 {
+  font-size: 1.3rem;
+  margin-bottom: 0.5rem;
+  color: #e8e8e8;
+}
+
+.discount {
+  font-size: 1.1rem;
+  color: #4a9eff;
+  font-weight: 600;
+  margin-bottom: 0.5rem;
+}
+
+.ends-in {
+  color: #888;
+  font-size: 0.9rem;
+  margin-bottom: 1rem;
+}
+
+.deal-card .btn {
+  align-self: flex-start;
+}
+
+/* ============================================
+   Editorial Section
+   ============================================ */
+
+.articles-grid {
+  display: grid;
+  grid-template-columns: repeat(auto-fit, minmax(350px, 1fr));
+  gap: 2rem;
+}
+
+.article-card {
+  background: rgba(40, 40, 40, 0.5);
+  border: 1px solid rgba(74, 158, 255, 0.15);
+  border-radius: 8px;
+  overflow: hidden;
+  transition: all 0.3s ease;
+  display: flex;
+  flex-direction: column;
+}
+
+.article-card:hover,
+.article-card:focus-within {
+  border-color: rgba(74, 158, 255, 0.4);
+  background: rgba(40, 40, 40, 0.8);
+  transform: translateY(-6px);
+  box-shadow: 0 15px 35px rgba(74, 158, 255, 0.15);
+}
+
+.article-image {
+  width: 100%;
+  height: 200px;
+  overflow: hidden;
+  background: linear-gradient(135deg, #2a2a2a 0%, #1a1a1a 100%);
+}
+
+.article-image img {
+  width: 100%;
+  height: 100%;
+  object-fit: cover;
+  transition: transform 0.4s ease;
+}
+
+.article-card:hover .article-image img,
+.article-card:focus-within .article-image img {
+  transform: scale(1.05);
+}
+
+.article-content {
+  padding: 1.5rem;
+  display: flex;
+  flex-direction: column;
+  flex-grow: 1;
+}
+
+.article-date {
+  color: #888;
+  font-size: 0.85rem;
+  margin-bottom: 0.75rem;
+}
+
+.article-content h3 {
+  font-size: 1.2rem;
+  margin-bottom: 1rem;
+  color: #e8e8e8;
+  line-height: 1.4;
+}
+
+.article-excerpt {
+  color: #b8b8b8;
+  margin-bottom: 1.5rem;
+  flex-grow: 1;
+  font-size: 0.95rem;
+}
+
+.article-link {
+  color: #4a9eff;
+  font-weight: 600;
+  display: inline-flex;
+  align-items: center;
+  gap: 0.5rem;
+  transition: all 0.3s ease;
+}
+
+.article-link:hover,
+.article-link:focus {
+  color: #66d9ff;
+  gap: 0.8rem;
+}
+
+/* ============================================
+   Newsletter Section
+   ============================================ */
+
+.newsletter-section {
+  background: linear-gradient(135deg, rgba(74, 158, 255, 0.1), rgba(102, 217, 255, 0.05));
+  border-top: 1px solid rgba(74, 158, 255, 0.3);
+  border-bottom: 1px solid rgba(74, 158, 255, 0.3);
+  padding: 4rem 0;
+}
+
+.newsletter-container {
+  text-align: center;
+}
+
+.newsletter-section h2 {
+  margin-bottom: 1rem;
+  padding-bottom: 0.5rem;
+}
+
+.newsletter-section h2::after {
+  display: none;
+}
+
+.newsletter-section p {
+  color: #b8b8b8;
+  margin-bottom: 2rem;
+  font-size: 1.1rem;
+}
+
+.newsletter-form {
+  display: flex;
+  gap: 0.5rem;
+  max-width: 500px;
+  margin: 0 auto;
+}
+
+.newsletter-form input {
+  flex: 1;
+  padding: 0.75rem 1rem;
+  border: 2px solid rgba(74, 158, 255, 0.3);
+  border-radius: 4px;
+  background: rgba(20, 20, 20, 0.8);
+  color: #e8e8e8;
+  font-size: 1rem;
+  transition: all 0.3s ease;
+}
+
+.newsletter-form input:hover,
+.newsletter-form input:focus {
+  border-color: #4a9eff;
+  background: rgba(20, 20, 20, 0.95);
+}
+
+.newsletter-form input::placeholder {
+  color: #666;
+}
+
+.newsletter-form button {
+  white-space: nowrap;
+}
+
+/* ============================================
+   Footer
+   ============================================ */
+
+.footer {
+  background: rgba(15, 15, 15, 0.95);
+  border-top: 1px solid rgba(74, 158, 255, 0.15);
+  padding: 3rem 0 1.5rem;
+  margin-top: 2rem;
+}
+
+.footer-content {
+  display: grid;
+  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
+  gap: 2rem;
+  margin-bottom: 2rem;
+}
+
+.footer-section h3 {
+  font-size: 1rem;
+  margin-bottom: 1rem;
+  color: #4a9eff;
+}
+
+.footer-section ul {
+  list-style: none;
+}
+
+.footer-section ul li {
+  margin-bottom: 0.75rem;
+}
+
+.footer-section a {
+  color: #b8b8b8;
+  transition: color 0.3s ease;
+}
+
+.footer-section a:hover,
+.footer-section a:focus {
+  color: #4a9eff;
+}
+
+.social-links {
+  display: flex;
+  flex-wrap: wrap;
+  gap: 1rem;
+}
+
+.footer-bottom {
+  border-top: 1px solid rgba(74, 158, 255, 0.1);
+  padding-top: 1.5rem;
+  text-align: center;
+  color: #666;
+  font-size: 0.9rem;
+}
+
+/* ============================================
+   Responsive Design
+   ============================================ */
+
+@media (max-width: 768px) {
+  .header-container {
+    padding: 1rem;
+    gap: 1rem;
+  }
+
+  .logo h1 {
+    font-size: 1.25rem;
+  }
+
+  .nav-primary ul {
+    gap: 1rem;
+    font-size: 0.85rem;
+  }
+
+  .hero-content h2 {
+    font-size: 2rem;
+  }
+
+  .hero {
+    padding: 4rem 1rem;
+  }
+
+  .products-grid {
+    grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
+    gap: 1rem;
+  }
+
+  .deals-grid {
+    grid-template-columns: 1fr;
+  }
+
+  .deal-card {
+    flex-direction: column;
+  }
+
+  .deal-image {
+    width: 100%;
+    height: 150px;
+  }
+
+  .articles-grid {
+    grid-template-columns: 1fr;
+  }
+
+  .newsletter-form {
+    flex-direction: column;
+  }
+
+  .newsletter-form button {
+    width: 100%;
+  }
+
+  main > section {
+    padding: 2rem 0;
+  }
+
+  main > section h2 {
+    font-size: 1.5rem;
+    margin-bottom: 2rem;
+  }
+
+  .footer-content {
+    grid-template-columns: repeat(2, 1fr);
+    gap: 1.5rem;
+  }
+}
+
+@media (max-width: 480px) {
+  body {
+    font-size: 0.9rem;
+  }
+
+  .hero-content h2 {
+    font-size: 1.5rem;
+  }
+
+  .hero {
+    padding: 2rem 1rem;
+  }
+
+  .container {
+    padding: 0 1rem;
+  }
+
+  main > section {
+    padding: 1.5rem 0;
+  }
+
+  main > section h2 {
+    font-size: 1.25rem;
+    margin-bottom: 1.5rem;
+  }
+
+  .product-info h3 {
+    font-size: 1rem;
+  }
+
+  .deal-card {
+    padding: 1rem;
+  }
+
+  .footer-content {
+    grid-template-columns: 1fr;
+    gap: 1.5rem;
+  }
+}
+
+/* ============================================
+   Forced Colors Mode (High Contrast)
+   ============================================ */
+
+@media (forced-colors: active) {
+  .btn-primary,
+  .btn-secondary,
+  .btn-accent {
+    border: 2px solid;
+    background: ButtonFace;
+    color: ButtonText;
+  }
+
+  .logo h1,
+  .hero-content h2 {
+    color: CanvasText;
+  }
+
+  a {
+    color: LinkText;
+  }
+
+  a:visited {
+    color: VisitedText;
+  }
+
+  .badge {
+    border: 2px solid;
+    background: ButtonFace;
+    color: ButtonText;
+  }
+
+  button:focus-visible {
+    outline: 3px solid;
+  }
+}
+
+/* ============================================
+   Reduced Motion
+   ============================================ */
+
+@media (prefers-reduced-motion: reduce) {
+  *,
+  *::before,
+  *::after {
+    animation-duration: 0.01ms !important;
+    animation-iteration-count: 1 !important;
+    transition-duration: 0.01ms !important;
+    scroll-behavior: auto !important;
+  }
+}
+
")
